import{z as s,x as A,o as E,c,q as o,j as l,D as e,d as i,s as r,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"动态离散选择","description":"","frontmatter":{"title":"动态离散选择","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-dynamic-discrete-choice.md","filePath":"econ/se-dynamic-discrete-choice.md","lastUpdated":1791413859000}'),d={name:"econ/se-dynamic-discrete-choice.md"};function p(m,a,u,C,h,D){const n=A("Mermaid");return E(),c("div",null,[a[2]||(a[2]=o('<h1 id="动态离散选择" tabindex="-1">动态离散选择 <a class="header-anchor" href="#动态离散选择" aria-label="Permalink to &quot;动态离散选择&quot;">​</a></h1><div class="epigraph"><p>换不换引擎不是看今天的维修账，是看里程这个状态通向的未来；把前向的账折成当期流效用，选择概率才与更换率对得上。</p><footer>—— 据 Rust, Optimal Replacement of GMC Bus Engines, Econometrica 1987 整理</footer></div><p><a href="/econ/se-blp-deep">上一课</a>把静态差异产品需求的工具与供给矩钉紧；那次购买没有日历。引擎更换、耐用品购买、出口参与、厂商退出，都是今天的选择改变明天的状态集，静态 logit 的弹性回答不了「何时」。本课把<a href="/econ/bellman-equation">贝尔曼方程</a>的动态结构变成可估模型：状态、流效用、转移、折现，加一层随机效用误差，就是动态离散选择。主干计量课的<a href="/econ/value-function-iteration">值函数迭代</a>在此从算法变成似然的内部器官。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Harold Zurcher 每月决定换不换公交引擎。状态 \\(x_t\\) 是里程，观测得到；\\(\\nu_t\\) 是他的维护生产率冲击，观测不到。他按</p> \\[V(x,\\nu)=\\max_{i\\in\\{0,1\\}}\\; u(x,i;\\theta) + \\varepsilon(i) + \\beta\\,\\mathbb{E}\\big[\\,V(x&#39;,\\nu&#39;) \\mid x, i\\,\\big] \\]<p>行动，转移 \\(p(x&#39;\\mid x,i)\\) 自己估计。缺口是三重的：这层不动点嵌在似然里，每个参数点都要重解一遍 \\(V\\)；\\(\\nu\\) 不可观测，选择之间存在模型没解释的序列相关；「结构性误差」\\(\\varepsilon\\) 的分布与流效用的量纲纠缠，不规范化就没有识别。</p><h3 id="嵌套不动点与-ccp-的分工" tabindex="-1">嵌套不动点与 CCP 的分工 <a class="header-anchor" href="#嵌套不动点与-ccp-的分工" aria-label="Permalink to &quot;嵌套不动点与 CCP 的分工&quot;">​</a></h3><p>标准写法（嵌套不动点）：给定 \\(\\theta\\)，用条件独立假设把 \\(\\nu\\) 折进期望值函数，收缩映射解出 \\(EV(x)\\)，选择概率取 logit 形式，再对更换记录算似然。CCP（Hotz and Miller 1993）：先非参数估条件选择概率，再把 continuation value 写成选择概率的函数，跳过逐参数重解不动点——用一步非参数估计换嵌套循环。两者估同一对象，计算量与稳健性是取舍，不是两套经济学。</p><p><span class="marginnote">Rust 的规范化：流效用只能定到差一个正常数与一个正尺度。常数由「差不影响选择」吸收，尺度与 \\(\\varepsilon\\) 的极值参数合并——通常把 \\(\\sigma\\) 定为 1，估出的是 \\(u/\\sigma\\) 与 \\(\\beta/\\sigma\\)。折现因子与误差尺度不分开识别，报告时必须写明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计分三段。第一段：状态的转移 \\(p(x&#39;\\mid x)\\) 单独极大似然，与偏好无关。第二段：偏好参数进似然或矩——嵌套不动点走 MLE；CCP 走把观测更换率与模型概率匹配的最小距离。第三段：状态空间大时，积分用模拟，下一单元的模拟矩课接上。反事实：改折旧规则、改引擎价格、强制里程上限，都在解好的策略函数上重放——<a href="/econ/lucas-critique">卢卡斯批判</a>在这里变成具体问题：若政策改变的是厂商对状态的感知而非回报，估好的策略不能外推。</p><p><span class="marginnote">数字实例：取 \\(\\beta=0.95\\)。今天省下 1000 元维修费，折到明年只值 950，后年 902……如此加总约等于今天的 20000 元（\\(1000/(1-0.95)\\)）。折现因子估错一点，这串未来的价就差出一大截——这正是它容易落在似然平谷里的原因。</span></p>',13)),(E(),l(B,null,{default:e(()=>[r(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E9%87%8C%E7%A8%8B%E4%B8%8E%E6%9B%B4%E6%8D%A2%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20TRANS%5B%22%E8%BD%AC%E7%A7%BB%20p(x'%7Cx%2Ci)%22%5D%0A%20%20TRANS%20--%3E%20EV%5B%22%E7%BB%99%E5%AE%9A%20%CE%B8%20%E8%A7%A3%20EV%22%5D%0A%20%20EV%20--%3E%20PROB%5B%22logit%20%E9%80%89%E6%8B%A9%E6%A6%82%E7%8E%87%22%5D%0A%20%20PROB%20--%3E%20EST%5B%22MLE%20%E6%88%96%20CCP%20%E6%9C%80%E5%B0%8F%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20EST%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%E5%87%BD%E6%95%B0%22%5D%0A%20%20POL%20--%3E%20CF%5B%22%E6%94%BF%E7%AD%96%E5%8F%8D%E4%BA%8B%E5%AE%9E%E9%87%8D%E6%94%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"机制是前向账本。今天换引擎，付出固定成本，买到重置后的低里程状态与未来的维修节省；不换，状态恶化但保留选择权。估出的参数是这份账本的系数。状态变量必须穷尽决策者信息：Zurcher 看得见的隐性损耗若不在 \\(x\\) 里，选择就有模型没解释的序列相关，估计会把它误读成折现或偏好。这也是不可观测状态 \\(\\nu\\) 要单独建模的原因——把看不见的异质扔进误差，参数全错。",-1)),(E(),l(B,null,{default:e(()=>[r(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%9C%AC%E6%9C%88%E9%87%8C%E7%A8%8B%E7%8A%B6%E6%80%81%20x%22%5D%20--%3E%7C%22%E6%8D%A2%E5%BC%95%E6%93%8E%22%7C%20R%5B%22%E4%BB%98%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%2C%20%E4%B9%B0%E5%88%B0%E4%BD%8E%E9%87%8C%E7%A8%8B%E6%96%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20X%20--%3E%7C%22%E4%B8%8D%E6%8D%A2%22%7C%20K%5B%22%E7%9C%81%E4%B8%8B%E4%BB%8A%E5%A4%A9%E7%9A%84%E9%92%B1%2C%20%E7%8A%B6%E6%80%81%E7%BB%A7%E7%BB%AD%E6%81%B6%E5%8C%96%22%5D%0A%20%20R%20--%3E%20F1%5B%22%E6%9C%AA%E6%9D%A5%E7%BB%B4%E4%BF%AE%E8%B4%B9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20K%20--%3E%20F2%5B%22%E6%9C%AA%E6%9D%A5%E7%BB%B4%E4%BF%AE%E8%B4%B9%E4%B8%8A%E5%8D%87%2C%20%E4%B8%94%E4%BF%9D%E7%95%99%E9%80%89%E6%8B%A9%E6%9D%83%22%5D%0A%20%20F1%20--%3E%20V%5B%22%E4%B8%A4%E6%9C%AC%E6%9C%AA%E6%9D%A5%E8%B4%A6%E5%90%84%E8%87%AA%E6%8A%98%E7%8E%B0%2C%20%E5%93%AA%E8%BE%B9%E5%A4%A7%E9%80%89%E5%93%AA%E8%BE%B9%22%5D%0A%20%20F2%20--%3E%20V%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">术语翻译：continuation value 就是「从明天的状态出发，往后所有日子的好处折回今天的总和」。今天的决定不只比今天的账，还要比两本「未来总账」的差——这正是它与静态 logit 的分界线：静态模型只有本月，看不见日历。</span></p><p>与<a href="/econ/se-blp-deep">上一课</a>对照：BLP 反演的对象是 \\(\\delta\\)（当期效用的位置），本课反演的对象是 continuation value；前者一份份额就有一个方程，后者要靠跨期变异与转移结构。识别都声明在「变异从哪来」，不在计算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课用条件独立与极值误差这两个强假设；它们放松时（误差序列相关、状态部分可观测），上面每个装置都要改装。大状态空间的职业选择模型（Keane–Wolpin 一类）要全新近似技术，本课不展开。折现因子与误差尺度的不分离是惯例性规范化，不是经济学结论。出口参与、退出这些结构性应用在下一课生产函数的深化里归位，本课不重复。</p><p><span class="marginnote">常见误区：初学者容易把静态 logit 估出的弹性直接拿去做政策外推。静态模型里「换不换」只看本月账，而政策（比如补贴新引擎）改变的是未来状态的回报——静态弹性根本看不见这一层，外推方向可能整个错掉。</span></p><p>后课默认：前向选择先写状态、转移与规范化，再谈估计；CCP 与嵌套不动点是同一模型的两种算法。不要把静态 logit 的更换弹性直接拿去做政策外推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态离散选择 = 状态 + 流效用 + 转移 + 折现 + 随机效用误差。</li><li>嵌套不动点解 \\(EV\\) 进似然；CCP 用选择概率反演 continuation value，省掉逐参数求解。</li><li>状态要穷尽决策者信息，漏掉的异质会伪装成折现与偏好。</li><li>尺度与折现不分开识别，规范化要写明。</li><li>出处：Rust, <em>Econometrica</em> 1987；Hotz and Miller, <em>REStud</em> 1993；McFadden, <em>Econometrica</em> 1989。</li></ul>',8))])}const x=s(d,[["render",p]]);export{_ as __pageData,x as default};
